const NOIR_DATA={"calle":"data:image/webp;base64,","nicolau":"data:image/webp;base64,","tienda":"data:image/webp;base64,","deposito":"data:image/webp;base64,","portrait-portell":"data:image/webp;base64,","portrait-nicolau":"data:image/webp;base64,","intro":"data:image/webp;base64,","taller":"data:image/webp;base64,"};
NOIR_DATA['nicolau-back']='data:image/webp;base64,';
'use strict';
/* =====================================================================
   DEPÓSITO CERO — aventura gráfica noir ochentera
   Motor + contenido. Sin dependencias externas salvo la tipografía.
   Arte: ilustración noir original y capas SVG interactivas.
   Música: sintetizada con WebAudio.
   ===================================================================== */

const $  = s => document.querySelector(s);
const byId = id => document.getElementById(id);

/* ============================ AUDIO ============================ */
const AudioEngine = {
  ctx:null, master:null, musicBus:null, playing:true, timer:null, beat:0, rainNode:null,
  init(){
    if(this.ctx) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if(!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain(); this.master.gain.value = .9;
    this.master.connect(this.ctx.destination);
    this.musicBus = this.ctx.createGain(); this.musicBus.gain.value = .8;
    this.musicBus.connect(this.master);
    this.startMusic();
  },
  now(){ return this.ctx ? this.ctx.currentTime : 0; },
  env(g,t,a,peak,d){
    g.gain.cancelScheduledValues(t);
    g.gain.setValueAtTime(0.0001,t);
    g.gain.linearRampToValueAtTime(peak,t+a);
    g.gain.exponentialRampToValueAtTime(0.0001,t+a+d);
  },
  tone(freq,t,dur,type='triangle',peak=.15,detune=0){
    if(!this.ctx) return;
    const o=this.ctx.createOscillator(), g=this.ctx.createGain();
    o.type=type; o.frequency.value=freq; o.detune.value=detune;
    this.env(g,t,.01,peak,dur);
    o.connect(g); g.connect(this.musicBus);
    o.start(t); o.stop(t+dur+.1);
  },
  noise(t,dur,freq=3000,q=1,peak=.12,dest=null){
    if(!this.ctx) return;
    const len = Math.max(1,(dur*this.ctx.sampleRate)|0);
    const buf = this.ctx.createBuffer(1,len,this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for(let i=0;i<len;i++) d[i]=Math.random()*2-1;
    const src=this.ctx.createBufferSource(); src.buffer=buf;
    const f=this.ctx.createBiquadFilter(); f.type='bandpass'; f.frequency.value=freq; f.Q.value=q;
    const g=this.ctx.createGain(); this.env(g,t,.005,peak,dur);
    src.connect(f); f.connect(g); g.connect(dest||this.master);
    src.start(t); src.stop(t+dur+.05);
  },
  /* Original nocturnal ambient score: slow pads, long chords and soft pulse. */
  pad(freq,t,dur,peak=.026){
    const c=this.ctx,filter=c.createBiquadFilter(),g=c.createGain();
    filter.type='lowpass';filter.frequency.setValueAtTime(650,t);filter.frequency.linearRampToValueAtTime(1500,t+dur*.45);filter.Q.value=.55;
    g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(peak,t+3.5);g.gain.setValueAtTime(peak*.8,t+dur-4);g.gain.exponentialRampToValueAtTime(.0001,t+dur);
    filter.connect(g);g.connect(this.musicBus);if(this.ambientSend)g.connect(this.ambientSend);
    [-6,6].forEach(detune=>{const o=c.createOscillator();o.type='sawtooth';o.frequency.value=freq;o.detune.value=detune;o.connect(filter);o.start(t);o.stop(t+dur+.1);});
  },
  startMusic(){
    if(!this.ctx||this.timer)return;
    const c=this.ctx,delay=c.createDelay(2),feedback=c.createGain(),air=c.createBiquadFilter();
    delay.delayTime.value=.69;feedback.gain.value=.38;air.type='lowpass';air.frequency.value=2200;
    delay.connect(air);air.connect(feedback);feedback.connect(delay);air.connect(this.musicBus);this.ambientSend=delay;
    const chords=[[130.8128,195.9977,246.9417,293.6648,391.9954],[110,164.8138,246.9417,329.6276,369.9944],[146.8324,220,261.6256,329.6276,440],[123.4708,184.9972,277.1826,329.6276,415.3047]];
    const beatDur=60/52;
    const step=()=>{
      if(!this.playing)return;
      const t=this.now()+.08,bar=Math.floor(this.beat/16)%chords.length,q=this.beat%16;
      if(q===0&&this.sax)this.sax(t,bar,beatDur);
      if(q===0){chords[bar].forEach((f,i)=>this.pad(f,t+i*.16,beatDur*19,.021));this.pad(chords[bar][0]/2,t,beatDur*19,.032);}
      if(q%4===0)this.tone(chords[bar][0]/2,t,2.5,'sine',.065);
      if(q===6||q===14)this.pad(chords[bar][q===6?3:4]*2,t,8,.009);
      this.beat++;
    };
    step();this.timer=setInterval(step,beatDur*1000);
  },
  toggleMusic(){
    this.playing = !this.playing;
    if(this.musicBus) this.musicBus.gain.value = this.playing ? .8 : 0;
    return this.playing;
  },
  rain(on){
    if(!this.ctx) return;
    if(on && !this.rainNode){
      const len = this.ctx.sampleRate*2;
      const buf = this.ctx.createBuffer(1,len,this.ctx.sampleRate);
      const d = buf.getChannelData(0);
      for(let i=0;i<len;i++) d[i]=(Math.random()*2-1)*.5;
      const src=this.ctx.createBufferSource(); src.buffer=buf; src.loop=true;
      const f=this.ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=900;
      const g=this.ctx.createGain(); g.gain.value=.045;
      src.connect(f); f.connect(g); g.connect(this.master); src.start();
      this.rainNode={src,g};
    } else if(!on && this.rainNode){
      try{this.rainNode.src.stop();}catch(e){}
      this.rainNode=null;
    }
  },
  click(){ this.init(); if(!this.ctx)return; this.tone(660,this.now(),.05,'square',.06); },
  pickup(){ this.init(); if(!this.ctx)return; const t=this.now(); this.tone(523.25,t,.09,'triangle',.12); this.tone(783.99,t+.09,.14,'triangle',.12); },
  deny(){ this.init(); if(!this.ctx)return; const t=this.now(); this.tone(196,t,.12,'sawtooth',.08); this.tone(185,t+.12,.18,'sawtooth',.08); },
  glitch(){ this.init(); if(!this.ctx)return; const t=this.now();
    this.tone(55,t,.35,'sawtooth',.16,12); this.noise(t,.3,900,2,.14); this.tone(61.7,t+.05,.3,'sawtooth',.1,-18); },
  success(){ this.init(); if(!this.ctx)return; const t=this.now();
    [220,277.18,329.63,440].forEach((f,i)=>this.tone(f,t+i*.1,.22,'triangle',.13)); },
  screech(){ this.init(); if(!this.ctx)return; const t=this.now();
    this.noise(t,1.1,1400,6,.10); this.noise(t+.15,.9,2600,8,.07); this.tone(1200,t,.9,'sine',.04,30); },
};

/* ============================ SVG: ESCENAS ============================ */
/* viewBox común 0 0 1600 900. Hotspots: formas con clase .hs y data-hs */

function rainLines(n,y0,y1,cls){
  let s=`<g class="rain ${cls||''}">`;
  for(let i=0;i<n;i++){
    const x=(i*97)%1600, y=y0+((i*173)%(y1-y0));
    s+=`<line x1="${x}" y1="${y}" x2="${x-14}" y2="${y+64}" style="animation-delay:${(i%10)*0.13}s"/>`;
  }
  return s+'</g>';
}
const NEON_DEFS = `
  <filter id="neonP" x="-60%" y="-60%" width="220%" height="220%">
    <feGaussianBlur stdDeviation="5" result="b"/>
    <feMerge><feMergeNode in="b"/><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
  </filter>
  <filter id="neonC" x="-60%" y="-60%" width="220%" height="220%">
    <feGaussianBlur stdDeviation="4" result="b"/>
    <feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
  </filter>`;

