function svgNicolauWalk(){return `<svg viewBox="0 0 502 1476" aria-hidden="true"><defs><clipPath id="nicoTop"><path fill-rule="evenodd" clip-rule="evenodd" d="M0 0H502V812H0Z M 22 280 L 120 292 L 142 358 L 126 430 L 106 489 L 108 559 L 151 669 L 166 770 L 141 807 L 76 800 L 47 714 L 17 594 L 0 520 L 9 391 Z M 314 292 L 350 308 L 371 397 L 383 483 L 402 548 L 409 627 L 443 714 L 445 764 L 410 804 L 365 801 L 349 765 L 359 693 L 340 608 L 331 532 L 311 451 Z"/></clipPath><clipPath id="nicoArmA"><path d="M 22 280 L 120 292 L 142 358 L 126 430 L 106 489 L 108 559 L 151 669 L 166 770 L 141 807 L 76 800 L 47 714 L 17 594 L 0 520 L 9 391 Z"/></clipPath><clipPath id="nicoArmB"><path d="M 314 292 L 350 308 L 371 397 L 383 483 L 402 548 L 409 627 L 443 714 L 445 764 L 410 804 L 365 801 L 349 765 L 359 693 L 340 608 L 331 532 L 311 451 Z"/></clipPath><clipPath id="nicoLeft"><rect y="812" width="256" height="664"/></clipPath><clipPath id="nicoRight"><rect x="256" y="812" width="246" height="664"/></clipPath></defs><g class="nico-front"><g class="fig"><g class="legA" style="transform-origin:40% 55%"><g clip-path="url(#nicoLeft)"><image href="${NOIR_DATA.nicolau}" width="502" height="1476"/></g></g><g class="legB" style="transform-origin:62% 55%"><g clip-path="url(#nicoRight)"><image href="${NOIR_DATA.nicolau}" width="502" height="1476"/></g></g><g clip-path="url(#nicoTop)"><image href="${NOIR_DATA.nicolau}" width="502" height="1476"/></g><g class="armB" style="transform-origin:66% 20%"><g clip-path="url(#nicoArmB)"><image href="${NOIR_DATA.nicolau}" width="502" height="1476"/></g></g><g class="armA" style="transform-origin:14% 19%"><g clip-path="url(#nicoArmA)"><image href="${NOIR_DATA.nicolau}" width="502" height="1476"/></g></g></g></g><image class="nico-back" href="${NOIR_DATA['nicolau-back']}" width="502" height="1476"/></svg>`;}
const NICO_ENTRY = { taller:84, calle:8, tienda:58, deposito:50 };
const nico = { x:78 };
function renderWalker(){
  const stage = byId('stage');
  let w = byId('nico');
  if(!w){
    w = document.createElement('div');
    w.id = 'nico'; w.className = 'walker';
    w.innerHTML = svgNicolauWalk();
    stage.appendChild(w);
  }
  w.classList.remove('at-table');
  const scale = {taller:62.5,calle:44,tienda:62.5,deposito:62.5};
  w.style.height = (scale[state.scene] || 62.5) + '%';
  w.style.transitionDuration = '0s';
  w.style.left = nico.x + '%';
}
function walkTo(xPct, done){
  const w = byId('nico');
  if(!w){ done && done(); return; }
  w.classList.remove('at-table');
  xPct = Math.max(12, Math.min(88, xPct));
  const dist = Math.abs(xPct - nico.x);
  if(dist < 1){ done && done(); return; }
  w.classList.toggle('flip', xPct < nico.x);
  const dur = Math.min(1.4, .3 + dist * .014);
  w.style.transitionDuration = dur + 's';
  w.classList.add('walking');
  nico.x = xPct;
  w.style.left = xPct + '%';
  clearTimeout(w._wtm);
  w._wtm = setTimeout(()=>{ w.classList.remove('walking'); done && done(); }, dur*1000+50);
}

