(function(){
  const objective0 = objective;
  objective = function(){
    if(F.intro && F.cinta_vista && !F.emulador_fallado) return 'Prueba la cinta en el emulador: toca la cinta del inventario (abajo) y luego el CRT.';
    if(F.intro && F.cinta_vista && F.emulador_fallado && !F.real_fallado) return 'Ahora en la máquina original: toca la cinta del inventario y luego el ZX de la mesa auxiliar.';
    return objective0();
  };
  const HINT = 'Primero tengo que probar la cinta: la selecciono en el inventario y la uso en el CRT y en el ZX.';
  const crt0 = HS.crt, spectrum0 = HS.spectrum, estanteria0 = HS.estanteria, osc0 = HS.osciloscopio;
  HS.crt = function(){
    if(F.cinta_vista && !F.emulador_fallado && !F.dump_ok){ say([{who:'NICOLAU', text:'Aquí toca probar la cinta. La selecciono en el inventario, abajo, y toco el CRT.'}]); return; }
    return crt0();
  };
  HS.spectrum = function(){
    if(F.cinta_vista && !F.real_fallado){ say([{who:'NICOLAU', text:'El 48K original. Para probar la cinta la selecciono en el inventario y toco el ZX.'}]); return; }
    return spectrum0();
  };
  HS.estanteria = function(){
    if(F.cinta_vista && !F.real_fallado){ say([{who:'NICOLAU', text:'Nueve años de software español, cada cinta con su ficha. Aún no sé qué piezas me faltan. '+HINT}]); return; }
    return estanteria0();
  };
  HS.osciloscopio = function(){
    if(F.cinta_vista && !F.real_fallado && !F.modulo){ say([{who:'NICOLAU', text:'El osciloscopio espera una señal que todavía no tengo. '+HINT}]); return; }
    return osc0();
  };
  const finishType0 = finishType;
  finishType = function(){
    finishType0();
    const L = dlg.lines[dlg.i];
    if(L && L.choices){ try{ byId('dialog-choices').scrollIntoView({behavior:'smooth', block:'nearest'}); }catch(e){} }
  };
})();

/* ===== v16: saxo melancólico sobre el ambient ===== */
AudioEngine.saxPhrases = [
  /* Do (Cmaj9): inicio de bar en pulsos, duración en pulsos, frecuencia */
  [[1,3,392.00],[4,2,493.88],[6,5,587.33],[11,2,493.88]],
  /* La */
  [[1,3,659.26],[4,3,493.88],[7,6,440.00]],
  /* Re */
  [[1,2,440.00],[3,2,523.25],[5,4,659.26],[9,2,587.33],[11,4,440.00]],
  /* Si */
  [[1,3,369.99],[4,3,415.30],[7,3,493.88],[10,6,369.99]]
];
AudioEngine.sax = function(t,bar,beatDur){
  const c=this.ctx; if(!c||!this.musicBus) return;
  const ph=this.saxPhrases[bar%this.saxPhrases.length];
  ph.forEach(([b,d,f],idx)=>{
    const t0=t+b*beatDur, dur=d*beatDur*0.96, peak=.05;
    const o1=c.createOscillator(), o2=c.createOscillator();
    o1.type='sawtooth'; o2.type='square';
    o1.frequency.setValueAtTime(f*0.972,t0); o1.frequency.exponentialRampToValueAtTime(f,t0+.09);
    o2.frequency.setValueAtTime(f*0.972,t0); o2.frequency.exponentialRampToValueAtTime(f*1.002,t0+.09);
    const lfo=c.createOscillator(), lg=c.createGain();
    lfo.frequency.value=5.1; lg.gain.setValueAtTime(0,t0); lg.gain.linearRampToValueAtTime(15,t0+Math.min(.9,dur*.7));
    lfo.connect(lg); lg.connect(o1.detune); lg.connect(o2.detune);
    const m2=c.createGain(); m2.gain.value=.28;
    const lp=c.createBiquadFilter(); lp.type='lowpass'; lp.Q.value=1.1;
    lp.frequency.setValueAtTime(900,t0); lp.frequency.linearRampToValueAtTime(1900,t0+.3); lp.frequency.linearRampToValueAtTime(1150,t0+dur);
    const body=c.createBiquadFilter(); body.type='peaking'; body.frequency.value=850; body.Q.value=1.2; body.gain.value=5;
    const g=c.createGain();
    g.gain.setValueAtTime(.0001,t0); g.gain.linearRampToValueAtTime(peak,t0+.11);
    g.gain.setValueAtTime(peak*.86,t0+Math.max(.2,dur-.5)); g.gain.exponentialRampToValueAtTime(.0001,t0+dur+.35);
    o1.connect(lp); o2.connect(m2); m2.connect(lp); lp.connect(body); body.connect(g);
    g.connect(this.musicBus); if(this.ambientSend){ const s=c.createGain(); s.gain.value=.7; g.connect(s); s.connect(this.ambientSend); }
    [o1,o2,lfo].forEach(o=>{ o.start(t0); o.stop(t0+dur+.45); });
    this.noise(t0,.28,2700,.8,.02,this.musicBus);
  });
};
